import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Scrumban Step-by-Step Activities","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","frontmatter":{"title":"Scrumban Step-by-Step Activities","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban Introduction, Scrumban Concept, What is Scrumban, Scrumban vs Kanban, Agile Methodology, Agile Framework, Kanban Methodology, Scrum Methodology, Scrumban Process, Scrumban Operation Guide, Scrumban Board, WIP Limit, Workflow Management, How to use Kanban Board, Scrumban Advantages, Scrumban Features, Scrumban Effects, Scrumban Use Cases, Scrumban Introduction Effects, Scrumban Jira Setup, Scrumban Board Template, Scrumban Tool, Scrumban Collaboration Tool, Scrumban Workflow, Agile Project Management, Work Efficiency Methodology, Iterative Work Management, Bottleneck Resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/activity.html"}]],"sort":400},"headers":[],"relativePath":"en/agile/activity.md","filePath":"en/agile/activity.md","lastUpdated":1784550502000}`),a={name:`en/agile/activity.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="scrumban-step-by-step-activity-guide" tabindex="-1">Scrumban Step-by-Step Activity Guide <a class="header-anchor" href="#scrumban-step-by-step-activity-guide" aria-label="Permalink to “Scrumban Step-by-Step Activity Guide”">​</a></h1><table tabindex="0"><thead><tr><th>Step</th><th>Main Activity</th><th>Detailed Description</th></tr></thead><tbody><tr><td><strong>1. Backlog</strong></td><td>- Collect new ideas/requests<br>- Record backlog items<br>- Assign class of service</td><td>The starting point for all work.<br><strong>Product Owner</strong> or team records business requests, bugs, technical debt, etc.<br>Assign <strong>priority</strong> and <strong>work type (Expedite, Fixed Date, Standard, Intangible)</strong> to each card.<br>Items in this stage are not yet ready to start.</td></tr><tr><td><strong>2. Ready</strong></td><td>- Check Definition of Ready (DoR)<br>- Break down work (if necessary)<br>- Unassigned handler</td><td>Details are prepared so work can start immediately.<br>Must meet DoR criteria (clear requirements, design/resources secured, test conditions defined, etc.).<br>Usually moved from Backlog to Ready during <strong>Replenishment meetings</strong>.</td></tr><tr><td><strong>3. Doing / In Progress</strong></td><td>- Start work (Pull)<br>- Update progress status<br>- Mark blockers</td><td>Team members pull from Ready to start within WIP limits.<br><strong>Bottlenecks/Blockers</strong> that occur during work are visually marked on the board (red labels, icons, etc.).<br>Share status in daily stand-ups.</td></tr><tr><td><strong>4. Review (Code Review / Peer Review)</strong></td><td>- Perform code review/document review<br>- Reflect feedback</td><td>Completed work is moved to the Review column.<br>Designated reviewers check for code quality and standard compliance.<br>If there is review feedback, it goes back to Doing or goes back to the Review stage after modification.</td></tr><tr><td><strong>5. Testing / QA</strong></td><td>- Functional testing<br>- Write bug reports and fix</td><td>QA or team members perform testing.<br>Can combine automated testing + manual testing.<br>If there is a bug, record it on the card and re-verify after fixing.</td></tr><tr><td><strong>6. Done</strong></td><td>- Confirm Definition of Done (DoD) is met<br>- Document/Update release notes<br>- Deployment complete</td><td>Meets all quality criteria and deployment is complete.<br>Includes documentation like release notes and user manuals.<br>Record completion date on the card (used for cycle time analysis).</td></tr></tbody></table><hr><h2 id="visualizing-the-activity-flow-for-each-stage" tabindex="-1">Visualizing the Activity Flow for Each Stage <a class="header-anchor" href="#visualizing-the-activity-flow-for-each-stage" aria-label="Permalink to “Visualizing the Activity Flow for Each Stage”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (Replenishment Meeting)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIP Check)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (Development Complete)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (Review Approved)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (Quality Verification Complete)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="operation-tips-per-stage" tabindex="-1">Operation Tips per Stage <a class="header-anchor" href="#operation-tips-per-stage" aria-label="Permalink to “Operation Tips per Stage”">​</a></h2><h3 id="_1-backlog" tabindex="-1">1. Backlog <a class="header-anchor" href="#_1-backlog" aria-label="Permalink to “1. Backlog”">​</a></h3><ul><li><strong>Clarify Priority Criteria</strong>: Based on urgency, value, deadlines, and risk</li><li><strong>Standardize Card Size</strong>: Split before Ready if too large</li><li><strong>Periodic Cleanup</strong>: Discard old/unnecessary cards</li></ul><h3 id="_2-ready" tabindex="-1">2. Ready <a class="header-anchor" href="#_2-ready" aria-label="Permalink to “2. Ready”">​</a></h3><ul><li><strong>Example of Definition of Ready (DoR) Checklist</strong><ul><li>Requirements are clear</li><li>Design/Data/Resources are secured</li><li>Test conditions are defined</li><li>Estimated work time/scope is confirmed</li></ul></li></ul><h3 id="_3-doing" tabindex="-1">3. Doing <a class="header-anchor" href="#_3-doing" aria-label="Permalink to “3. Doing”">​</a></h3><ul><li>Maintain the <strong>Stop Starting, Start Finishing</strong> rule</li><li>Discuss immediately when bottlenecks occur</li><li>Minimize multitasking</li></ul><h3 id="_4-review" tabindex="-1">4. Review <a class="header-anchor" href="#_4-review" aria-label="Permalink to “4. Review”">​</a></h3><ul><li>Define code review criteria (e.g., code style, performance, security, tests included)</li><li>Utilize notification systems to reduce review wait time</li></ul><h3 id="_5-testing" tabindex="-1">5. Testing <a class="header-anchor" href="#_5-testing" aria-label="Permalink to “5. Testing”">​</a></h3><ul><li>Parallel use of automated testing and manual testing</li><li>Re-verify after fixing on the same card when bugs occur</li><li>WIP limit exceptions can be allowed if a test fails</li></ul><h3 id="_6-done" tabindex="-1">6. Done <a class="header-anchor" href="#_6-done" aria-label="Permalink to “6. Done”">​</a></h3><ul><li><strong>Record cycle time</strong> on the card upon completion</li><li>Review completed cards during release retrospectives</li><li>Assign tags for data analysis (bugs, new features, etc.)</li></ul><hr><h2 id="key-metrics-per-stage" tabindex="-1">Key Metrics per Stage <a class="header-anchor" href="#key-metrics-per-stage" aria-label="Permalink to “Key Metrics per Stage”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Key Metric</th><th>Purpose of Utilization</th></tr></thead><tbody><tr><td>Backlog → Ready</td><td>Lead Time (Request ~ Ready to Start)</td><td>Identify causes of preparation delays</td></tr><tr><td>Ready → Doing</td><td>Pull Frequency</td><td>Grasp the team&#39;s throughput capacity</td></tr><tr><td>Doing</td><td>Average WIP, Blocker Ratio</td><td>Bottleneck management</td></tr><tr><td>Review</td><td>Review Wait Time</td><td>Balance between quality and speed</td></tr><tr><td>Testing</td><td>Defect Rate, Rework Rate</td><td>QA efficiency</td></tr><tr><td>Done</td><td>Cycle Time, Throughput</td><td>Improve predictability</td></tr></tbody></table><hr><p>By organizing this way, it becomes clear <strong>what teams adopting Scrumban should do at each stage</strong>, and <strong>metric-based improvement activities</strong> can also be conducted concurrently.</p><hr>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};